from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = next(v for row in grid for v in row if v != bg)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    out = [row[:] for row in grid]
    if not points:
        return out
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    # Complete the top and bottom horizontal strokes across the foreground
    # bounding box, using 2 for the missing cells.
    for r in {top, bottom}:
        for c in range(left, right + 1):
            if grid[r][c] == bg:
                out[r][c] = 2
    # Extend recurring vertical strokes (at least three foreground marks)
    # across the full foreground vertical extent.
    for c in range(w):
        if sum(grid[r][c] == fg for r in range(h)) >= 3:
            for r in range(top, bottom + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
